#!/usr/bin/env python3
"""Refresh AnjanaPS_files/scholar.js from the public Google Scholar profile.

Run by the Pages workflow before each deploy (and on a weekly schedule).
If Scholar can't be reached or the page layout changed, the existing
scholar.js is left untouched, so the site always shows the last good numbers.
"""
import datetime
import json
import pathlib
import re
import sys
import urllib.request

PROFILE_ID = "XI9eymcAAAAJ"
URL = f"https://scholar.google.com/citations?user={PROFILE_ID}&hl=en"
OUT = pathlib.Path(__file__).resolve().parents[2] / "AnjanaPS_files" / "scholar.js"


def main() -> int:
    try:
        with urllib.request.urlopen(URL, timeout=30) as resp:
            html = resp.read().decode("utf-8", "ignore")
    except Exception as exc:  # network error, 429, captcha redirect...
        print(f"Scholar fetch failed, keeping existing data: {exc}")
        return 0

    stats = re.findall(r'class="gsc_rsb_std">(\d+)<', html)
    since = re.search(r'class="gsc_rsb_sth">\s*(Since \d{4})\s*<', html)
    years = [int(y) for y in re.findall(r'class="gsc_g_t"[^>]*>(\d{4})<', html)]

    # Each bar is <a class="gsc_g_a" style="...z-index:N"><span class="gsc_g_al">C</span></a>.
    # z-index counts back from the latest year; years with 0 citations have no bar.
    bars = re.findall(
        r'class="gsc_g_a"[^>]*z-index:(\d+)[^>]*>\s*<span class="gsc_g_al">(\d+)<', html
    )

    if len(stats) < 6 or not years:
        print("Scholar page layout not recognised, keeping existing data")
        return 0

    by_year = {y: 0 for y in years}
    for z, count in bars:
        idx = len(years) - int(z)
        if 0 <= idx < len(years):
            by_year[years[idx]] = int(count)

    data = {
        "profile": f"https://scholar.google.com/citations?user={PROFILE_ID}",
        "updated": datetime.date.today().isoformat(),
        "sinceLabel": since.group(1) if since else "Recent",
        "citations": {"all": int(stats[0]), "since": int(stats[1])},
        "hIndex": {"all": int(stats[2]), "since": int(stats[3])},
        "i10Index": {"all": int(stats[4]), "since": int(stats[5])},
        "byYear": [{"year": y, "count": by_year[y]} for y in years],
    }

    OUT.write_text(
        "/* Generated by .github/scripts/update_scholar.py - do not edit by hand. */\n"
        "window.SCHOLAR_STATS = " + json.dumps(data, indent=2) + ";\n"
    )
    print(f"Updated {OUT.name}: {data['citations']['all']} citations")
    return 0


if __name__ == "__main__":
    sys.exit(main())
